INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118354, 'spa', 'Nof (Menfis, ciudad egipcia)', 'Nombre propio de la antigua ciudad egipcia Menfis (egipcio Mn-nfr, «belleza perdurable»), al sur del delta del Nilo. Fue capital política y religiosa de Egipto. En la profecía representa el poder egipcio y la falsa seguridad: Oseas 9:6 advierte que «Mof los sepultará», Isaías 19:13 declara engañados a sus príncipes y Ezequiel 30:13 anuncia la destrucción de sus ídolos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118359, 'spa', 'Nombre propio', 'Nombre propio que llevan dos figuras bíblicas: un levita del linaje de Coat y uno de los hijos de David. Las transliteraciones en inglés, español, francés y alemán son muy consistentes (Nepheg, Nefeg, Néfeg), lo que demuestra que se trata de un nombre propio con transmisión interlingüística estable. Algunas versiones encierran entre corchetes la forma conjuntiva [וְנֶפֶג] para indicar complejidad morfológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118361, 'spa', 'Alturas de Dor', 'Las tres apariciones se refieren a la misma ubicación geográfica: el territorio elevado en torno a Dor. Las traducciones al español conservan el concepto de elevación («alturas»). La combinación constructa con Dor funcionaba como un topónimo fijo más que como una frase descriptiva. La evidencia arqueológica confirma el carácter escarpado de la región costera donde se asentaba Dor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118363, 'spa', 'Soplar, insuflar', 'Soplar o insuflar con propósito y fuerza dirigida. Este es el sentido activo principal: Dios insuflando el aliento de vida en Adán (Gn 2:7), el mandato a los cuatro vientos de soplar sobre los muertos en el valle de los huesos secos (Ez 37:9) y el soplar sobre metal en un horno para calentarlo (Ez 22:20-21; Is 54:16). El español «soplar» capta la exhalación enérgica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118364, 'spa', 'Resoplar con desprecio', 'Uso en Hifil: resoplar o soplar con desdén sobre algo que merece honor. En Malaquías 1:13, los sacerdotes tratan la mesa de la ofrenda del SEÑOR con desprecio, «soplando sobre ella» como si fuera indigna de atención. Una imagen vívida de irreverencia expresada mediante el gesto físico del soplo desdeñoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118367, 'spa', 'Exhalar, expirar', 'Exhalar el último aliento — expirar, morir. En Jeremías 15:9, la madre de siete «exhaló su alma» (naphchah nafshah) al ponerse el sol, una representación conmovedora de la vida que se va como el aliento que abandona el cuerpo. El español «echó» (soltó, liberó) capta la finalidad de esa última exhalación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118368, 'spa', 'Soplado, calentado', 'Sentido participial pasivo de algo que ha sido soplado — calentado, hirviente o avivado. Una olla «soplada» (naphuach) mira al norte en Jeremías 1:13, y el aliento de Leviatán es como un caldero «soplado» en Job 41:20. La imagen es de un trabajo sostenido de fuelle que produce calor intenso y peligroso. El resultado es un estado, no la acción misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118372, 'spa', 'Hacer expirar, expulsar', 'Sentido causativo del Hifil: hacer que la vida de alguien expire o expulsar mediante el soplo. En Job 31:39, Job protesta su inocencia negando haber «hecho exhalar la vida de sus dueños» — es decir, no los ha matado de agotamiento ni los ha desposeído fatalmente. Señala a un agente que fuerza el cese del aliento ajeno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118376, 'spa', 'Gigantes primordiales', 'En Génesis, los nefilim surgen en la era en que los «hijos de Dios» tomaron esposas humanas, engendrando «hombres poderosos de la antigüedad, varones de renombre», una referencia oscura que sugiere un origen y poder anormales. En Números se los menciona dos veces: primero como temidos habitantes de Canaán y luego identificando a los anaceos como sus descendientes. El terror de los espías («parecíamos langostas») muestra cómo los nefilim funcionaban como símbolo del poder invencible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118378, 'spa', 'Persona y tribu', 'Dos apariciones son genealógicas, estableciendo a Nafis como undécimo hijo de Ismael en la lista canónica. La tercera referencia (1 Crónicas 5:19) transita de persona a pueblo: los nafisitas como tribu derrotada por los clanes orientales de Israel. Las traducciones multilingües muestran transliteración simple con variaciones fonéticas menores. El patrón de nombre personal convertido en designación tribal es típico de las genealogías del Génesis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118379, 'spa', 'Piedra preciosa', 'Piedra preciosa valorada por su uso ornamental y simbólico. Las traducciones divergen notablemente: el inglés prefiere «turquoise», el español oscila entre «esmeralda» y «carbunclo», el francés emplea «turquoise» o «émeraude» y el alemán «Türkis». Esta variación léxica refleja las antiguas incertidumbres sobre la identificación de gemas. La piedra aparece en contextos de gran valor: vestiduras sacerdotales y la riqueza de Tiro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118380, 'spa', 'caer físicamente (Qal)', 'Caída física nuclear: desplomarse o derrumbarse al suelo. El árabe emplea سَقَطَ (saqaṭa) ''caer'', confirmando el sentido primario a través de las lenguas semíticas. Gn 17:3 presenta a Abraham cayendo sobre su rostro ante Dios — postura de reverencia. Gn 45:14 muestra a José echándose al cuello de Benjamín en un abrazo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118390, 'spa', 'yacer caído (participio Qal)', 'Participio Qal estativo: yacer caído, estar postrado. No el evento de caer sino el estado resultante. Nm 24:4, 16 describen a Balaam como ''el que cae'' y con los ojos abiertos — postura visionaria. Dt 21:1 trata de un cadáver ''tendido'' en el campo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118396, 'spa', 'desertar, pasarse al enemigo', 'Sentido militar especializado: desertar, pasarse al bando enemigo. 2 R 25:11 habla de los desertores que se pasaron a los babilonios. Jer 37:13-14 acusa al profeta de deserción, usando el participio ''desertores''. La metáfora: caer del propio bando al del adversario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118401, 'spa', 'caer sobre, atacar (Qal)', 'Sentido Qal de caer sobre alguien hostilmente: atacar, asaltar. 2 S 17:9 advierte que Absalón ''caerá sobre'' las tropas de David. Job 4:13, 33:15 describen visiones que ''caen'' sobre uno en el sueño profundo — una irrupción casi invasiva, abrumadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118403, 'spa', 'echar suertes (Hifil)', 'Hifil especializado para echar suertes o arrojar objetos: acción proyectiva deliberada. 1 Cr 24:31, 25:8, 26:13-14 describen las suertes que determinan las divisiones levíticas. El español echaron y el coreano 제비를 뽑았다 (''echaron suertes'') confirman el desplazamiento semántico de caer a arrojar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118404, 'spa', 'derribar, abatir (Hifil)', 'Hifil causativo: ''hacer caer'', ''derribar'', ''abatir''. Gn 2:21 presenta a Dios haciendo caer un sueño profundo sobre Adán. Dt 25:2 permite al juez hacer caer (azotar) al culpable. El matiz marcial aparece con frecuencia: hacer caer a los enemigos equivale a derrotarlos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118409, 'spa', 'postrarse en adoración (Hitpael)', 'Hitpael reflexivo: postrarse deliberadamente en adoración o reverencia. No caída accidental sino acto intencional de echarse al suelo. Dt 9:18, 25 presentan a Moisés postrado ante YHWH durante cuarenta días. Esd 10:1 muestra a Esdras postrado en oración. La morfología reflexiva señala agentividad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118431, 'spa', 'repartir por suerte (Hifil)', 'Hifil para repartir o distribuir tierra por sorteo. Jos 13:6 (''yo la repartiré a Israel'') y 23:4 describen la distribución de la conquista. Sal 78:55 recuerda cómo Dios ''les repartió'' la tierra de las naciones — un sorteo divino que determinó la herencia tribal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118461, 'spa', 'derribar (uso aislado)', 'Sentido incierto, aparece una vez en 2 R 3:25 con el verbo ''derribaron''. Posible término militar especializado para demoler o abatir, pero la evidencia es singular y no permite conclusiones firmes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118466, 'spa', 'desmontar, descender (Qal)', 'Sentido especializado: desmontar, descender de una cabalgadura. El árabe emplea نَزَلَ (nazala) ''descender/desmontar'', confirmando un campo semántico distinto de la caída accidental. Gn 24:64 presenta a Rebeca desmontando de su camello al ver a Isaac. 2 R 5:21 muestra a Giezi bajando — descenso controlado, no derrumbe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118498, 'spa', 'dejar caer, descuidar (Hifil)', 'Hifil con sentido de dejar caer, soltar o descuidar. Pr 19:15 advierte que la pereza hace ''caer'' en el hambre. Est 6:10 ordena a Amán que ''no deje caer nada'' (no descuide nada) de su encargo. El árabe cambia a تُهْمِلْ (descuidar), un dominio semántico completamente distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118515, 'spa', 'dar a luz (metáfora)', 'Sentido incierto, aparece una vez en Is 26:19 donde la tierra ''dará a luz'' o ''echará fuera''. El hebreo puede implicar una metáfora de parto o expulsión, pero las traducciones divergen ampliamente. Probablemente imagen de resurrección cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118556, 'spa', 'recibir herencia (uso aislado)', 'Sentido incierto, aparece una vez en Ez 47:22 donde los extranjeros ''caerán'' como herencia. Probablemente relacionado con la acepción 6 (reparto por sorteo), pero la sintaxis es inusual y sugiere que ''caer en herencia'' funciona como modismo de adjudicación territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118560, 'spa', 'Caer, postrarse', 'Caer o caer postrado — en el arameo de Daniel para caer en adoración (Dn 3:5-7, 10-11, 15), postrarse rostro en tierra en reverencia (Dn 2:46), ser arrojado al horno (Dn 3:23), una voz divina que desciende sobre el rey (Dn 4:28) y cuernos que caen ante un poder mayor (Dn 7:20). Abarca la caída física, la postración cultual y el descenso metafórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118567, 'spa', 'Aborto o mortinato', 'Los tres usos son metafóricos o comparativos: el mortinato como símbolo de no existencia o vida desperdiciada. El anhelo de Job, la maldición del salmista y la reflexión filosófica de Qohélet invocan el patetismo de la criatura que entra en la existencia solo para salir de inmediato. Las traducciones interlingüísticas se centran en la caída prematura y la vida frustrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118568, 'spa', 'Piel', 'Piel: destrozar, hacer pedazos — La forma intensiva Piel: aplastar o estrellar algo violentamente hasta hacerlo añicos, usado predominantemente de Dios o un agente divino destruyendo enemigos, naciones o ídolos. La imagen del cetro de hierro en el Salmo 2:9 y el mazo de guerra en Jeremías 51:20-23 son paradigmáticas. El Salmo 137:9 extiende esta acción al caso más perturbador. El español ''destrozar'' y el alemán ''zerschmettern'' transmiten la naturaleza total y violenta de la destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118569, 'spa', 'Pasivo', 'Pasivo: ser quebrantado, despedazado — La voz pasiva: estar destrozado, quebrado, en un estado de destrucción ya consumado. Jeremías 22:28 pregunta si Conías es una ''vasija despreciada y rota'' (נָפוּץ), e Isaías 27:9 describe piedras de altar ''desmenuzadas'' (מְנֻפָּצוֹת). El español ''quebrado'' y ''desmenuzadas'' captan el estado resultante más que el acto de romper.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118574, 'spa', 'Piel', 'Piel: dispersar, esparcir — Dispersar o esparcir, extendiendo la metáfora del quebranto desde objetos físicos a personas o grupos. En Daniel 12:7, la ''dispersión del poder del pueblo santo'' (נַפֵּץ יַד) no es un quebranto literal sino la dispersión y desempoderamiento de una nación. El español ''dispersar'' distingue este sentido de la destrucción concreta del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118577, 'spa', 'Qal', 'Qal: romper, quebrar — La raíz Qal básica: romper o quebrar sin la fuerza intensiva del Piel. En Jueces 7:19, los trescientos de Gedeón quiebran sus cántaros (וַיִּנְפְּצוּ הַכַּדִּים) como señal militar — un acto decisivo y repentino de rotura, no una destrucción violenta y sostenida. La construcción de infinitivo absoluto enfatiza la naturaleza súbita y coordinada de la acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118578, 'spa', 'Dispersar o esparcir', 'Describe la acción de dispersar o esparcir, generalmente referida a poblaciones humanas. En 1 Samuel 13:11, el pueblo «se dispersaba» de Saúl; en Génesis 9:19, la humanidad «se esparció» por la tierra; Isaías 11:12 y 33:3 hablan de «las dispersas de Judá» y de naciones que se esparcen. La evidencia multilingüe muestra de manera consistente verbos de dispersión, a veces con indicaciones de formas morfológicas inusuales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118580, 'spa', 'Sacar, hacer salir (Hifil)', 'Sentido causativo Hafel (Hifil): sacar, hacer salir, extraer. Cinco apariciones describen a un agente retirando objetos de un lugar. Ciro sacó los utensilios de oro y plata que Nabucodonosor había tomado del templo de Jerusalén (Esd 5:14), y ordenó su devolución (Esd 6:5). Belsasar mandó traer esos mismos utensilios para su banquete (Dan 5:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118581, 'spa', 'Salir, surgir (Qal)', 'Sentido intransitivo Pe''al (Qal): salir, surgir, emerger de un lugar. Siete apariciones describen movimiento físico hacia afuera. Un decreto real ''salió'' (Dan 2:13), Daniel ''salió'' al encuentro de Arioc (Dan 2:14), Sadrac, Mesac y Abed-nego ''salieron'' ilesos del horno (Dan 3:26), y unos dedos misteriosos ''aparecieron'' y escribieron en la pared de yeso (Dan 5:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118589, 'spa', 'Descansar y reponerse', 'Dos pasajes del Éxodo vinculan el refrigerio con el reposo sabático, tanto para los trabajadores como, notablemente, para Dios mismo tras la creación (31:17). Este antropomorfismo afirma el genuino costo de crear. El caso de David (2 Samuel 16:14) es más literal: tropas agotadas que recuperan el aliento. Las traducciones multilingües destacan la renovación y el descanso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118590, 'spa', 'alma, ser interior', 'El yo interior inmaterial o alma (647 apariciones): sede de las emociones, la voluntad y la vida espiritual. Gn 49:6 (''no entre mi alma en su consejo'') y Sal 42:1 muestran a נֶפֶשׁ como el ser consciente y sensible que se relaciona con Dios y con los demás. Es el sentido dominante en prácticamente todos los géneros literarios bíblicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118599, 'spa', 'vida, vitalidad', 'La vida física o existencia vital (94 apariciones) que puede arriesgarse, perderse o salvarse. Éx 21:23 (''vida por vida'') y Éx 4:19 (''los que buscaban tu vida'') muestran a נֶפֶשׁ como lo que está en juego ante un peligro mortal, algo concretamente amenazado más que un estado interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118633, 'spa', 'persona, individuo', 'Una persona o individuo como unidad contable (5 apariciones), especialmente en contextos legales y censales. Lv 27:2 (''la valoración de personas'') y Dt 24:7 (''quien secuestre a una persona'') tratan a נֶפֶשׁ como una cabeza humana que se enumera o sobre la que se legisla, despojada de sus connotaciones emotivas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118634, 'spa', 'deseo, apetito', 'Deseo, apetito o anhelo volitivo (9 apariciones). Gn 23:8 (''si es vuestro deseo'') y Dt 23:24 (''come uvas hasta saciar tu deseo'') muestran a נֶפֶשׁ como la facultad apetitiva: aquello que el ser busca, ya sea alimento, posesión o un ser amado (Gn 34:3, 8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118663, 'spa', 'aliento, soplo vital', 'Aliento o soplo de vida (1 aparición en Job 41:21), que describe la exhalación ígnea de Leviatán. ''Su aliento'' capta la imagen respiratoria física. Este uso infrecuente preserva el vínculo etimológico entre נֶפֶשׁ y נָפַשׁ (''respirar''), anclando el concepto abstracto de alma en la respiración concreta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118674, 'spa', 'ser viviente (principio vital)', 'El principio animador que constituye un ser viviente (1 aparición en Gn 2:7), donde Dios sopla en Adán y este se convierte en ''נֶפֶשׁ viviente''. No se trata de un alma que entra en un cuerpo, sino de polvo que se transforma en criatura dotada de alma. Este versículo fundacional ancla todo el rango semántico del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118703, 'spa', 'Miel virgen del panal', 'Miel que fluye naturalmente del panal, representando la dulzura más fina. El Salmo 19:10 la empareja con דְּבַשׁ como comparación superlativa para las ordenanzas divinas. Proverbios 27:7 nota que incluso nópheth resulta repugnante al saciado. Se emplea figuradamente para el habla seductora (Pr 5:3) y los labios de la amada (Cnt 4:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118707, 'spa', 'El nombre propio Neftalí, que abarca al patriarca (Gn 30', 'El nombre propio Neftalí, que abarca al patriarca (Gn 30:8; 35:25; 46:24; 49:21), la tribu descendiente de él como unidad administrativa y militar (Jue 1:33; 4:6, 10; 5:18; Dt 33:23), y el territorio tribal en el norte de Canaán centrado en Cedes de Neftalí (Jos 19:32-39; 20:7). Isaías 9:1 [8:23] transforma el nombre en un marcador escatológico — la ''tierra de Neftalí'' que será honrada con una gran luz, pasaje que Mateo aplica al ministerio de Jesús en Galilea (Mt 4:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118716, 'spa', 'Gavilán o halcón', 'Las leyes alimentarias agrupan al gavilán con águilas, buitres y otras rapaces como ritualmente impuro, quizá por alimentarse de carroña o sangre. La referencia poética de Job pasa de la prohibición a la admiración: la sabiduría migratoria del gavilán testifica del diseño del Creador plasmado en la naturaleza. Las traducciones interlingüísticas son directas: gavilán, halcón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118718, 'spa', 'Nifal intransitivo', 'Nifal intransitivo: estar de pie, permanecer en pie, apostarse — el sentido dominante con 42 ocurrencias. Cubre la postura física en la narrativa: tres hombres están de pie ante Abraham (Gn 18:2), Rebeca está junto al manantial (Gn 24:43), la gavilla de José se yergue en su sueño (Gn 37:7), y el SEÑOR está por encima de la escalera en Betel (Gn 28:13). El español de pie y el alemán standen apuntan a la simple postura erguida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118720, 'spa', 'Participio Nifal lexicalizado como sustantivo', 'Participio Nifal lexicalizado como sustantivo: un oficial, supervisor o gobernador apostado — 8 ocurrencias, todas en contextos administrativos. Los nitstsavim de Salomón gobiernan los doce distritos de Israel (1 R 4:7, 27), abastecen la mesa real (1 R 4:5) y supervisan los trabajos forzados (1 R 5:16). El paso metafórico de ''uno que está apostado'' a ''un funcionario con un puesto'' resulta transparente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118721, 'spa', 'Hifil causativo', 'Hifil causativo: erigir, levantar o apostar a alguien o algo en su lugar — 19 ocurrencias centradas en el establecimiento deliberado de objetos o personas. Abraham coloca las siete corderas (Gn 21:28), Jacob erige una estela (Gn 35:14, 20), y Samuel presenta al pueblo ante el SEÑOR (1 S 10:19). El árabe naṣaba (''erigir un poste de tienda o marcador'') y el francés dresser (''levantar en posición vertical'') captan este matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118729, 'spa', 'Hofal pasivo', 'Hofal pasivo: ser erigido, ser decretado — 3 ocurrencias donde algo ha sido establecido por un agente externo. La escalera de Jacob está ''puesta'' alcanzando el cielo (Gn 28:12), el pilar ''erigido'' en la coronación de Abimelec junto al Milo (Jue 9:6), y el decreto de Nínive queda ''establecido'' (Nah 2:7). El español puesta y el francés dressa (pasivo) confirman la lectura pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118737, 'spa', 'Una única ocurrencia Nifal en el Sal 119', 'Una única ocurrencia Nifal en el Sal 119:89 donde el sentido es ''estar establecido, permanecer firme'', aplicado a la palabra de Dios en los cielos: ''Para siempre, oh SEÑOR, tu palabra está firme en los cielos''. El español está firme y el alemán ist gegründet (''está fundado'') seleccionan vocabulario de permanencia y estabilidad cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118744, 'spa', 'Hifil abstracto-causativo', 'Hifil abstracto-causativo: establecer o afianzar — 2 ocurrencias donde la erección es figurada más que física. David va a ''establecer'' su monumento en el Éufrates (1 Cr 18:3), y Dios ''establecerá'' el lindero de la viuda (Pr 15:25). El árabe yuthabbitu (''afianzar, consolidar'') capta la firmeza metafórica que distingue este sentido de la erección concreta de pilares del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118772, 'spa', 'Luchar, contender, reñir', 'Trabar conflicto físico o verbal con otra parte, de forma recíproca (Nifal) o agresiva contra alguien (Hifil). El Nifal capta la lucha mutua: dos hombres peleando (Éx 2:13; 21:22; Dt 25:11), un israelita y un extranjero riñendo en el campamento (Lv 24:10), y dos hermanos forcejeando (2 S 14:6). El Hifil aparece en Nm 26:9 para la rebelión de Coré.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118778, 'spa', 'Destrucción urbana', 'Las tres apariciones retratan la destrucción urbana mediante juicio militar. Jeremías profetiza la desolación venidera, mientras los paralelos de Isaías y Reyes reflexionan sobre la devastación asiria pasada. El participio Nifal «montones de ruinas» (גַּלִּים נִצִּים) combina dos vocablos de destrucción para intensificar el efecto. Las traducciones multilingües se centran en ruina y destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118780, 'spa', 'El participio Piel usado como sustantivo en 56 títulos de salmos', 'El participio Piel usado como sustantivo en 56 títulos de salmos: lamnatseach, ''al director'' o ''para el director musical''. Es el uso más frecuente y reconocible, funcionando como una rúbrica litúrgica técnica. El español al director, el francés au chef de musique y el coreano indobajayege (''al director'') identifican a un líder de culto responsable de la interpretación. Habacuc 3:19 también emplea este término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118781, 'spa', 'El infinitivo y participio Piel con el significado de ''supervisar, dirigir o adm', 'El infinitivo y participio Piel con el significado de ''supervisar, dirigir o administrar'', aplicado a la construcción y trabajos administrativos más que a la música. 1 Crónicas 23:4 asigna 24.000 levitas ''para supervisar'' (lenatseach) la obra del templo, y 2 Crónicas 2:2, 2:18, 34:12-13 usan el participio plural menatschim para capataces y supervisores. El español capataces y el francés diriger (''dirigir'') confirman el matiz administrativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118783, 'spa', 'Un único participio Nifal femenino en Jeremías 8', 'Un único participio Nifal femenino en Jeremías 8:5: meshuvah nitsachat, ''apostasía perpetua''. Aquí aflora el sentido subyacente de la raíz referido a duración y permanencia — no liderazgo, sino persistencia incesante. El español perpetua y el significado contextual de ''apostasía implacable'' distinguen este sentido claramente de los sentidos musical y de supervisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118789, 'spa', 'El sentido temporal-adverbial dominante', 'El sentido temporal-adverbial dominante: perpetuidad, para siempre, eternamente. Casi siempre precedido por la preposición lamed (la-netsach) o ad (ad-netsach), funciona como adverbio temporal en lamentos sálmicos (''¿Me olvidarás para siempre?'' Sal 13:1), juicio profético (''desolaciones perpetuas,'' Sal 74:3) y enseñanza sapiencial (Prov 21:28). Aparece en 39 de las 43 ocurrencias del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118794, 'spa', 'Resistencia personal o fortaleza duradera, que aparece únicamente en Lam 3', 'Resistencia personal o fortaleza duradera, que aparece únicamente en Lam 3:18 donde el poeta clama ''mi resistencia (nitschi) ha perecido.'' El sufijo pronominal personaliza el concepto abstracto — no se trata de la perpetuidad cósmica sino de la capacidad de una persona para soportar, ahora quebrantada. El léxico BDB conecta esto con el significado raíz de ''savia de vida.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118795, 'spa', 'Eminencia o gloria divina, un sentido casi único en 1 Sam 15', 'Eminencia o gloria divina, un sentido casi único en 1 Sam 15:29 donde Samuel declara que ''la Eminencia de Israel no mentirá ni se arrepentirá.'' Aquí נֵצַח funciona como epíteto divino paralelo a הוֹד (''majestad'') y תִּפְאֶרֶת (''esplendor''). El término enfatiza la preeminencia inmutable y trascendente de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118796, 'spa', 'Fin o completitud, que aparece una vez en Job 34', 'Fin o completitud, que aparece una vez en Job 34:36 donde Elihú expresa el deseo de que Job sea probado ''hasta el fin'' (ad netsach). Aquí el sentido temporal se desliza hacia la finalidad — no duración sin fin sino la conclusión de un proceso. El significado contextual se acerca más a ''a fondo, hasta la consumación.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118801, 'spa', 'Victoria o triunfo, una única ocurrencia en 1 Cr 29', 'Victoria o triunfo, una única ocurrencia en 1 Cr 29:11 dentro de la gran doxología de David: ''Tuya, oh SEÑOR, es la grandeza, y el poder, y la gloria, y la victoria (ha-netsach), y la majestad.'' Esta lectura, respaldada por el νῖκος de la LXX y la victoria de la Vulgata, influyó en la lectura cristiana de 1 Cor 15:54-55 (''La muerte ha sido tragada en victoria'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118803, 'spa', 'Guarnición militar', 'Guarnición o puesto militar estacionado para control territorial. Las guarniciones filisteas en Geba y otros lugares (1 Sam 10:5; 13:3-4) representan la ocupación extranjera; las guarniciones de David en Aram y Edom (2 Sam 8:6, 14) marcan el dominio israelita. El término implica no solo soldados, sino una instalación permanente de autoridad sobre el territorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118805, 'spa', 'Gobernador, funcionario', 'Gobernador, prefecto o intendente designado para administrar una región. En 1 Reyes 4:19 se nombra a un gobernador sobre Galaad, mientras que 2 Crónicas 8:10 cuenta los oficiales principales de Salomón. El énfasis recae en la autoridad administrativa más que en la presencia armada, diferenciándose así del sentido militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118809, 'spa', 'Columna, pilar erguido', 'Columna o pilar erguido, una estructura física vertical. Génesis 19:26 usa netsiv para la columna de sal en que se convirtió la mujer de Lot. Este sentido concreto e inanimado se distingue de los significados humanos e institucionales, conservando la idea raíz de algo ''estacionado'' o puesto en posición vertical.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118813, 'spa', 'librar, rescatar, salvar (Hifil)', 'El Hifil causativo dominante: librar, rescatar o salvar a alguien del peligro, de enemigos o de la muerte. Con 188 apariciones es el centro gravitacional de נצל — desde la liberación pascual (Éx 12:27) hasta la alabanza davídica (2 S 22:1). El árabe أنجد/نجّى, el español librar y el coreano 건지다 convergen en extracción forzosa del peligro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118834, 'spa', 'tizón arrebatado del fuego', 'Imagen profética de ''tizón arrebatado del fuego'' — rescate en el último instante antes de la aniquilación. Am 4:11 y Zac 3:2 forman una vívida metáfora de escape al filo de la destrucción total. El español arrebatado marca la intensidad del rescate desesperado, más allá de la simple liberación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118845, 'spa', 'ser librado, escapar (Nifal)', 'El Nifal pasivo-reflexivo: ser librado, escapar o librarse a sí mismo. Quince apariciones, entre ellas la liberación de Jacob en Peniel (Gn 32:30) y la súplica del salmista desde el fango (Sal 69:14). El árabe يَنْجو (''escapar''), el coreano 구원받다 (''recibir salvación'') y la ley del esclavo fugitivo de Dt 23:15 confirman tanto el matiz pasivo como el reflexivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118854, 'spa', 'despojar, saquear (Piel)', 'El Piel intensivo: despojar, saquear, expoliar — el opuesto semántico del verbo. Tres apariciones: Israel despojó a los egipcios (Éx 3:22, 12:36) y el ejército de Josafat saqueó a los moabitas caídos (2 Cr 20:25). El árabe سلب (''saquear'') y el coreano 빼앗다 (''arrebatar'') confirman una inversión total desde la liberación hasta la expoliación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118876, 'spa', 'despojarse (Hitpael reflexivo)', 'Un Hitpael reflexivo singular en Éx 33:6: Israel ''se despojó de'' sus ornamentos en Horeb tras el juicio del becerro de oro. El español se despojaron y el francés se dépouilla confirman la acción de quitarse adornos dirigida a uno mismo — semánticamente cercana al Piel de despojo, pero reflexiva y penitencial en vez de depredadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118878, 'spa', 'arrebatar, quitar (Hifil)', 'Un matiz Hifil distinto de arrebatar o quitar posesiones por la fuerza — no rescate sino incautación. Dios ''quitó'' el ganado de Labán para Jacob (Gn 31:9, 16) y Oseas advierte de la expropiación divina (Os 2:9). El árabe انتزع (''arrancar'') y el hindi छीना (''arrebatado'') emplean raíces por completo distintas del vocabulario de rescate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118934, 'spa', 'Rescate divino', 'Las tres apariciones se centran en el rescate divino milagroso de una ejecución, ya sea por fuego o por leones. Daniel 3:29 celebra el poder liberador único de Dios tras el episodio del horno. Daniel 6:14 muestra a Darío desesperado «por rescatar» a Daniel del foso, mientras 6:27 alaba a Dios que «rescata y libra». Los verbos emparejados subrayan una salvación integral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118937, 'spa', 'El sentido pactual dominante', 'El sentido pactual dominante: guardar, custodiar u observar mandamientos, leyes, estipulaciones del pacto e instrucciones morales con obediencia cuidadosa y deliberada. Representa 24 de las 64 ocurrencias, concentradas en Salmos y Proverbios. El español guardar y el alemán bewahren captan la dimensión de custodia — no mero cumplimiento, sino preservación atesorada de lo que ha sido encomendado. El Salmo 119 está saturado de este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118938, 'spa', 'Participio sustantivado', 'Participio sustantivado: un vigilante, centinela, guardián o custodio — 11 ocurrencias donde el verbo se convierte en nombre de agente. Los notsrim de 2 Reyes 17:9 y 18:8 son centinelas de atalayas militares, mientras que Job 7:20 se dirige provocadoramente a Dios como ''oh, Vigilante de los hombres''. Jeremías 31:6 imagina a los notsrim en el monte Efraín convocando al pueblo hacia Sion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118941, 'spa', 'Guardar, proteger o preservar a una persona del daño o el peligro — 20 ocurrenci', 'Guardar, proteger o preservar a una persona del daño o el peligro — 20 ocurrencias, frecuentemente con Dios como sujeto que resguarda a los fieles. En Deuteronomio 32:10, Dios ''guardó'' a Israel ''como la niña de su ojo'', y el Salmo 32:7 declara que Dios ''me preservará de la angustia''. El español guarda y el francés garder tratan la protección y la observancia de mandamientos con el mismo verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118942, 'spa', 'Sitiar o bloquear una ciudad — 4 ocurrencias que constituyen un sentido militar ', 'Sitiar o bloquear una ciudad — 4 ocurrencias que constituyen un sentido militar diferenciado. En Isaías 1:8 Jerusalén es ''como una ciudad sitiada''; Jeremías 4:16 advierte que ''sitiadores vienen de tierra lejana''; Ezequiel 6:12 distingue al sitiado del que está lejos. El español sitiada/sitiadores deja claro que no se trata de simple custodia metafórica, sino de un cerco militar real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118951, 'spa', 'Participio pasivo', 'Participio pasivo: lo que está oculto, escondido, guardado o mantenido en secreto — 5 ocurrencias que forman un sentido adjetival diferenciado. Proverbios 7:10 describe a una mujer con un ''corazón cauteloso/astuto'' (netsurath lev); Isaías 48:6 revela ''cosas ocultas que no has conocido''; Isaías 49:6 habla de ''los preservados de Israel''. La morfología pasiva desplaza la semántica de la vigilancia activa al resultado de haber sido guardado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118985, 'spa', 'Brote o vástago', 'Metáfora botánica para designar nuevo crecimiento, descendencia o sucesión que emerge de un tronco o raíz. Isaías 11:1 lo emplea mesiánicamente («vástago de Isaí»), mientras que Isaías 60:21 lo aplica a Israel como plantío de Dios. Daniel 11:7 habla de «un retoño de sus raíces» en el contexto de sucesión dinástica. Las glosas multilingües lo traducen consistentemente como «brote/retoño/vástago» (retoño, branche, Zweig).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118987, 'spa', 'Designar, especificar o señalar por nombre, a menudo en contexto oficial o forma', 'Designar, especificar o señalar por nombre, a menudo en contexto oficial o formal. Números 1:17 registra que ciertos hombres fueron ''designados por nombre'' para el censo, y 1 Crónicas 12:32 y 16:41 lo emplea para personas nombradas al servicio. Génesis 30:28 tiene a Labán pidiendo a Jacob que ''especifique'' su salario. La metáfora subyacente puede ser la de ''señalar'' o marcar a alguien dentro del grupo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118988, 'spa', 'Maldecir, injuriar o blasfemar, usado especialmente para proferir imprecaciones ', 'Maldecir, injuriar o blasfemar, usado especialmente para proferir imprecaciones contra una persona o blasfemar el Nombre divino. Levítico 24:11 narra el caso fundacional: un hombre ''traspasó'' (blasfemó) el Nombre y fue apedreado. Números 23:8 y 23:25 lo emplean para la incapacidad de Balaam de maldecir a Israel. El vínculo semántico con ''perforar'' sugiere una concepción antigua de la maldición como penetración verbal en lo sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118989, 'spa', 'Perforar, agujerear o traspasar físicamente un objeto con herramienta o arma', 'Perforar, agujerear o traspasar físicamente un objeto con herramienta o arma. En 2 Reyes 12:9 el sacerdote perfora la tapa de un cofre, y 2 Reyes 18:21 advierte que apoyarse en Egipto es como apoyarse en una caña que traspasa la mano. Job 40:24 y 41:2 preguntan si se puede perforar la nariz o la quijada de Leviatán. Este es el núcleo concreto y literal del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119006, 'spa', 'Criatura hembra, ya sea humana (mujer, niña) o animal, empleada para marcar la d', 'Criatura hembra, ya sea humana (mujer, niña) o animal, empleada para marcar la distinción de sexo en contextos legales, cúlticos y narrativos. Aparece casi siempre emparejada con זָכָר (''macho''). Predomina en los textos sacerdotales que tratan de la creación (Gn 1:27; 5:2), las parejas del diluvio (Gn 6:19; 7:3, 9, 16), las regulaciones sacrificiales (Lv 3-5) y las leyes de pureza (Lv 12; 15). Jeremías 31:22 la despliega en un enigmático oráculo profético de inversión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119012, 'spa', 'Moteado, salpicado', 'Moteado o salpicado en el pelaje, usado exclusivamente de ovejas y cabras en las narraciones ganaderas de Jacob y Labán (Gn 30:32-39; 31:8, 10, 12). El adjetivo suele aparecer en listas junto a עָקֹד (listado) y טָלוּא (manchado), distinguiendo las motas finas de las manchas más grandes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119017, 'spa', 'Pan desmenuzado o tortas', 'La narración del engaño gabaonita emplea esta palabra para demostrar que viajaron desde lejos: provisiones frescas ahora secas y desmenuzadas. El griego βεβρωμένοι (mohoso) y el latín in frusta comminuti (desmenuzado en pedazos) captan el deterioro. En 1 Reyes el contexto cambia a provisiones aptas como regalo, sugiriendo un alimento preparado. Las traducciones al español alternan entre «mohoso» y «tortas».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119019, 'spa', 'El sentido jurídico del Nifal de quedar impune o ser declarado inocente — el uso', 'El sentido jurídico del Nifal de quedar impune o ser declarado inocente — el uso más frecuente con 15 ocurrencias, casi siempre en la fórmula negativa lo yinnaqeh (''no quedará impune''). Proverbios concentra esta fórmula densamente (6:29; 11:21; 16:5; 17:5; 19:5, 9; 28:20), estableciéndola como máxima sapiencial sobre la consecuencia inevitable del mal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119020, 'spa', 'El sentido declarativo del Piel — absolver, declarar inocente o dejar impune — c', 'El sentido declarativo del Piel — absolver, declarar inocente o dejar impune — con Dios o un juez como sujeto en 15 ocurrencias. El núcleo teológico aparece en la gran autorrevelación divina en el Sinaí: ''que de ningún modo absolverá al culpable'' (Éx 34:7; Nm 14:18), donde el infinitivo absoluto duplicado נַקֵּה לֹא יְנַקֶּה crea certeza enfática.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119021, 'spa', 'El sentido de purificación del Nifal — ser limpiado o purgado de culpa o impurez', 'El sentido de purificación del Nifal — ser limpiado o purgado de culpa o impureza moral — en 3 ocurrencias donde el énfasis recae en la purificación interior más que en el veredicto judicial. El salmista pregunta ''¿quién puede discernir sus propios errores? Límpiame de los que me son ocultos'' (Sal 19:13), usando נָקָה para la purificación moral que solo Dios puede realizar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119028, 'spa', 'El sentido del Nifal de liberación de obligación — quedar libre o exento de un j', 'El sentido del Nifal de liberación de obligación — quedar libre o exento de un juramento, voto o responsabilidad legal — con 7 ocurrencias en contextos narrativos. El siervo de Abraham queda ''libre de este juramento'' si la mujer no quiere seguirlo (Gn 24:8, 41); quien hiere a otro queda ''absuelto'' si la víctima se recupera (Éx 21:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119034, 'spa', 'Una única ocurrencia enigmática en Isaías 3', 'Una única ocurrencia enigmática en Isaías 3:26 donde las puertas de Jerusalén ''gimen y se lamentan, y ella, vaciada (neqqetah), se sentará en el suelo.'' Aquí la raíz retorna a su núcleo etimológico de vaciamiento o desolación — la ciudad despojada de habitantes y gloria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119039, 'spa', 'El sentido del Piel de purificación de culpa de sangre — limpiar o vengar sangre', 'El sentido del Piel de purificación de culpa de sangre — limpiar o vengar sangre inocente — en 3 ocurrencias donde el Piel lleva una fuerza ritual o vindicatoria más allá de la mera absolución legal. Joel 3:21 declara ''limpiaré su sangre que aún no he limpiado,'' donde el verbo revela la metáfora de purificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119049, 'spa', 'Nombre propio personal', 'Nombre personal y familiar entre los exiliados que regresaron, asociado específicamente con la clase de los netineos. Aparece en listas censales duplicadas (Esdras 2 // Nehemías 7), rasgo habitual de los registros genealógicos postexílicos. Las traducciones son consistentes en diversos idiomas (Nekoda, Necoda, Necodá), aunque algunas encierran el hebreo [נקודא] para señalar que se trata de una forma transliterada o incierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119051, 'spa', 'Libre de culpa o reproche, que no merece castigo — el sentido dominante que abar', 'Libre de culpa o reproche, que no merece castigo — el sentido dominante que abarca la gran mayoría de las ocurrencias. Central a la preocupación deuteronómica por la ''sangre inocente'' (dam naqi), que no debe ser derramada en la tierra (Dt 19:10). Los amigos y enemigos de Job debaten su inocencia usando precisamente esta palabra (Job 4:7; 9:23; 22:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119057, 'spa', 'Liberado o libre de una obligación vinculante, juramento o penalidad', 'Liberado o libre de una obligación vinculante, juramento o penalidad. En Génesis 24:41, el siervo de Abraham quedará ''libre'' (naqi) de su juramento si la mujer se niega a venir. Deuteronomio 24:5 exime al recién casado — estará ''libre'' (naqi) para su hogar durante un año. Este sentido jurídico de liberación se distingue de la inocencia moral del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119059, 'spa', 'Exento de un deber cívico o militar obligatorio', 'Exento de un deber cívico o militar obligatorio. En 1 Reyes 15:22 se registra el decreto de Asá de que ''ninguno quedaba exento'' (en naqi) del trabajo forzado para construir Geba y Mizpa. Se trata de libertad no de culpa sino de servicio obligatorio — un sentido administrativo y cívico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119060, 'spa', 'Limpio y puro, ya sea física, ritual o éticamente', 'Limpio y puro, ya sea física, ritual o éticamente. El Salmo 24:4 pregunta ''¿Quién subirá al monte del SEÑOR?'' y responde: el que tiene ''manos limpias y corazón puro'' (neqi khappayim uvar levav). Este sentido se solapa con la inocencia pero enfatiza la limpieza interior y ritual más que la absolución forense.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119063, 'spa', 'Inocencia moral', 'Designa la inocencia moral y ritual, el estado de estar libre de culpa o de transgresión. La expresión «inocencia de manos» aparece en Génesis 20:5, Salmo 26:6 y 73:13, significando una conducta limpia e irreprochable. Las traducciones multilingües emplean de forma constante terminología de inocencia (inocencia, innocent, Reinheit), confirmando que se trata fundamentalmente de un término ético-moral. En Oseas 8:5 se desplaza levemente hacia la idea de exención del castigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119065, 'spa', 'Hendidura rocosa', 'Las tres apariciones ocurren en oráculos de juicio donde las hendiduras simbolizan escondites que resultan inútiles. En Isaías albergarán ejércitos invasores; en Jeremías se convierten en lugar para objetos proféticos o terreno de pesca donde nadie escapa del cazador divino. La forma constructa siempre especifica «de la roca», vinculando el término inseparablemente al paisaje pétreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119066, 'spa', 'Hitpael reflexivo-intensivo', 'Hitpael reflexivo-intensivo: vengarse con fuerza enfática o repetida — 5 ocurrencias, todas en retórica profética. La pregunta tres veces repetida de Jeremías ''¿No me vengaré de una nación como esta?'' (Jer 5:9, 29; 9:9) usa el Hitpael para transmitir la deliberación sostenida y escrutadora de Dios antes del juicio. La morfología intensivo-reflexiva sugiere no un acto único sino una postura continua de juicio ponderado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119067, 'spa', 'Piel intensivo', 'Piel intensivo: ejecutar venganza de manera completa y deliberada — solo 2 ocurrencias, en 2 Reyes 9:7 (Jehú es ungido para ''vengar'' la sangre de los profetas contra la casa de Jezabel) y Jeremías 51:36 (Dios ''vengará'' a Israel contra Babilonia). La intensificación del Piel señala una retribución integral y divinamente ordenada — no parcial ni personal, sino la liquidación total de cuentas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119068, 'spa', 'Nifal reflexivo', 'Nifal reflexivo: vengarse o ser vengado — el grupo más numeroso con 13 ocurrencias, que cubre construcciones de voz media donde el sujeto sufre el agravio y ejecuta la retribución. El castigo del amo de esclavos ''será vengado'' (Éx 21:20-21), Sansón clama ''que me vengue de los filisteos'' (Jue 16:28), y el juramento precipitado de Saúl ata a Israel hasta que ''me haya vengado de mis enemigos'' (1 Sam 14:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119069, 'spa', 'Hofal pasivo', 'Hofal pasivo: ser vengado (de la sangre o la víctima) — 2 ocurrencias, ambas en Génesis 4, estableciendo el principio de la venganza de sangre en los albores de la historia humana. A Caín se le dice que quien lo mate ''será vengado siete veces'' (Gn 4:15), y Lamec se jacta de una venganza de setenta y siete veces (Gn 4:24). El pasivo Hofal coloca la sangre de la víctima como sujeto — es la sangre la que ''es vengada.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119070, 'spa', 'Participio Qal', 'Participio Qal: el vengador, quien toma venganza — 5 ocurrencias, concentradas en el teológicamente denso Nahúm 1:2, donde tres formas participiales se acumulan: Dios es נֹקֵם (''vengador''), נֹקֵם de nuevo (por énfasis), y בַּעַל חֵמָה. También en Levítico 26:25 (''espada vengadora del pacto'') y Salmo 99:8 (''un Dios vengador'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119075, 'spa', 'Qal activo', 'Qal activo: tomar venganza contra un enemigo o malhechor — 8 ocurrencias de verbos finitos e infinitivos en la conjugación activa básica. Moisés recibe la orden de ''vengar a los israelitas de los madianitas'' (Nm 31:2); el sol se detiene ''hasta que la nación se vengó'' (Jos 10:13); y el gran Cántico de Moisés declara que Dios ''vengará la sangre de sus siervos'' (Dt 32:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119092, 'spa', 'Venganza, retribución — Venganza o retribución como concepto teológico y jurídic', 'Venganza, retribución — Venganza o retribución como concepto teológico y jurídico, que describe con mayor frecuencia el castigo decisivo de Dios contra sus enemigos y los violadores del pacto. La frase ''venganza del pacto'' en Levítico 26:25 lo vincula explícitamente con la aplicación del pacto. Deuteronomio 32:35 declara ''mía es la venganza'', estableciendo la prerrogativa exclusiva de Yahvé para retribuir. Isaías emplea el término en expresiones como ''día de venganza'' (34:8; 61:2) y ''vestiduras de venganza'' (59:17), retratando a Dios como guerrero-juez. En el uso humano excepcional — el acto final de Sansón en Jueces 16:28 y el rencor de los edomitas en Ezequiel 25:12 — el término subraya cuán profundamente personal era el concepto de represalia en el pensamiento israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119097, 'spa', 'Justicia retributiva o venganza, predominantemente divina, ejecutada contra los ', 'Justicia retributiva o venganza, predominantemente divina, ejecutada contra los transgresores del pacto y los enemigos nacionales. Central en la teología profética: Jeremías anuncia la venganza de YHWH contra Babilonia (Jer 50:15, 28; 51:6, 11, 36), Ezequiel la declara contra Edom y Filistea (Ez 25:14, 17), y Jeremías la invoca en lamento personal (Jer 11:20; 20:12). En los Salmos, Dios es ''el Dios de las venganzas'' (Sal 94:1) que concede vindicación entre los pueblos (Sal 18:47; 2 S 22:48).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119107, 'spa', 'Enajenación divina', 'Las tres apariciones ocurren en un solo capítulo (Ezequiel 23), formando un estribillo en la alegoría de las ciudades hermanas. La frase «mi alma se apartó» capta la profunda repulsión de Dios ante la adulteración espiritual: su afecto y compromiso arrancados por la infidelidad persistente. La estructura paralela intensifica el rechazo divino con cada repetición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119109, 'spa', 'Recorrer en circuito — Ir alrededor, circundar o rodear en sentido no hostil', 'Recorrer en circuito — Ir alrededor, circundar o rodear en sentido no hostil: una marcha procesional, descripción arquitectónica o movimiento de reconocimiento. Josué 6:3 y 6:11 describen a Israel rodeando Jericó como acto ritual de fe, mientras que el Salmo 48:12 invita a los peregrinos a ''rodear a Sion, circundarla''. En 1 Reyes 7:24 y 2 Crónicas 4:3, describe calabazas ornamentales rodeando el borde del mar de bronce.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119113, 'spa', 'Cortar en redondo — Cortar o recortar de manera circular, específicamente la prá', 'Cortar en redondo — Cortar o recortar de manera circular, específicamente la práctica prohibida de rasurar los bordes de la cabeza en Levítico 19:27. Esta única aparición aplica el significado de movimiento circular de la raíz al acto de recortar el cabello alrededor de las sienes, práctica asociada con ritos paganos de duelo. El español ''cortaréis en redondo'' hace explícita la geometría espacial de la acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119114, 'spa', 'Rodear o cercar con hostilidad — Rodear o circundar con intención hostil', 'Rodear o cercar con hostilidad — Rodear o circundar con intención hostil: enemigos, peligros o juicio divino cerrándose desde todos los lados. El Salmo 17:9 describe a enemigos mortales que ''me rodean'', y el Salmo 22:17 hace eco con ''perros me han rodeado''. Job 19:6 lo aplica a la red de Dios cerrándose sobre un sufriente. En 2 Reyes 6:14, el ejército arameo rodea Dotán de noche. El español ''rodear/cercar'' y la construcción Hifil consistente refuerzan el sentido de cerco amenazante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119124, 'spa', 'Completar un ciclo — Completar un ciclo completo de eventos recurrentes', 'Completar un ciclo — Completar un ciclo completo de eventos recurrentes: días, fiestas o tiempos señalados que llegan a su término. En Job 1:5, después de que los hijos de Job ''terminaban'' su ronda de días de banquete, Job madrugaba para ofrecer sacrificios. Isaías 29:1 usa el Qal imperfecto: ''que las fiestas cumplan su ciclo''. El contexto temporal muestra que se trata de una completación cíclica, no de un movimiento espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119127, 'spa', 'Horadar, arrancar, sacar', 'Horadar, arrancar o sacar con fuerza, describiendo principalmente la extraccion violenta de ojos. El Qal aparece en 1 Samuel 11:2 (la amenaza de Najas) y Proverbios 30:17 (cuervos que sacan el ojo); el Piel intensifica en Jueces 16:21 (ceguera de Sanson). Job 30:17 extiende la imagen a huesos perforados; Isaias 51:1 usa el Pual para la cantera de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119134, 'spa', 'Tender trampa o lazo', 'Poner un lazo o tender una trampa a alguien, maquinando activamente su caída. El Salmo 38:12 describe enemigos que tienden trampas; el Salmo 109:11 imagina al acreedor atrapando los bienes del malvado. Deuteronomio 12:30 advierte a Israel contra ser enredado por prácticas de culto pagano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119136, 'spa', 'Ner — Nombre propio masculino que significa ''lámpara'', identificando a un ancest', 'Ner — Nombre propio masculino que significa ''lámpara'', identificando a un ancestro benjaminita dentro del linaje real de Saúl. El nombre aparece casi exclusivamente en la fórmula patronímica ''Abner hijo de Ner'' a lo largo de Samuel y Reyes (1 Sam 14:50; 26:5, 14; 2 Sam 2:8, 12; 3:23, 25, 28, 37). La genealogía del Cronista ubica a un Ner como padre de Cis (1 Cr 8:33; 9:39), planteando interrogantes sobre si se trata de uno o dos individuos. Ner es conocido principalmente como padre de Abner, el poderoso comandante militar de Saúl.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119139, 'spa', 'Nergal-Saréser (oficial babilonio)', 'Nombre propio compuesto de un dignatario babilonio, Nergal-Saréser (acadio Nergal-shar-usur, «oh Nergal, protege al rey»), quien ostentaba el título de Rab-mag («jefe de los magos») en el ejército de Nabucodonosor II. En Jeremías 39:3 se le menciona entre quienes se sentaron en la puerta central de Jerusalén tras su caída, y en Jer 39:13 participa en la liberación de Jeremías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119143, 'spa', 'Murmurar y calumniar', 'Describe el acto de murmurar con rebeldía o susurrar con malicia. Los pasajes de Proverbios se centran en el «chismoso» (נִרְגָּן), figura que esparce contienda mediante el chisme y la calumnia. Las traducciones interlingüísticas reflejan ambos aspectos: español «chismoso/murmurador», francés «calomniateur», inglés «whisperer». Las formas entre corchetes como [ונרגן] y [נרגן] pueden indicar variación textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119144, 'spa', 'Planta aromática', 'Las tres apariciones se encuentran en la celebración de la fragancia y la belleza del Cantar de los Cantares. El posesivo «mi nardo» (1:12) sugiere posesión personal de un perfume costoso. El plural «nardos» (4:13) puede indicar variedades múltiples o simple intensificación poética junto a otros aromáticos. La mención final (4:14) lo coloca primero entre las especias exóticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119145, 'spa', 'Nerías (nombre propio)', 'Nombre propio Nerías/Neriyahu, que significa ''lámpara de Yahveh'', identifica al padre de Baruc el escriba y de Seraías. Se le menciona constantemente en fórmulas patronímicas (''Baruc hijo de Nerías'') a lo largo de la narración de Jeremías. La forma teofórica larga Neriyahu (Jer 36:14; 43:6; 45:1) alterna libremente con la forma corta Neriyah (Jer 32:12; 36:4), como es habitual en los nombres con sufijo -yahu/-yah.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119147, 'spa', 'Cargar, transportar', 'Llevar cargas físicas (205 apariciones), distinto de meramente alzar. Las varas diseñadas ''para llevar'' el arca (Éx 25:14), los levitas como ''portadores''. El participio ''portadores de'' aparece frecuentemente en contextos de servicio sacerdotal y transporte del tabernáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119148, 'spa', 'Alzar, levantar', 'Movimiento ascendente físico o metafórico en 330 apariciones. Abraham ''alzó sus ojos'' (Gn 18:2), Jacob ''alzó su voz y lloró'' (Gn 21:16). Abarca alzar ojos, manos, voz, cabeza y objetos abstractos. Corresponde al sentido básico e intransitivo del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119177, 'spa', 'Soportar, sufrir consecuencia', 'Cargar culpa o castigo como consecuencia (17 veces), distinto de perdonar. ''La tierra no podía sostenerlos'' (Gn 13:6). ''Lleva tu propia iniquidad'' (Ez 4:4-6). El sujeto padece la carga en vez de removerla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119184, 'spa', 'Perdonar pecado', 'El modismo teológico ''cargar/quitar el pecado'' (נָשָׂא עָוֹן/חַטָּאת) aparece 23 veces significando ''perdonar''. Moisés suplica: ''Perdona nuestra iniquidad'' (Éx 34:9). El hebreo retiene la imagen de ''levantar y llevarse'' la culpa ajena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119196, 'spa', 'Mostrar parcialidad', 'El modismo נָשָׂא פָנִים (''alzar el rostro'') = mostrar parcialidad, 7 apariciones. ''El SEÑOR no hace acepción de personas'' (Dt 10:17). La imagen evoca levantar la mirada hacia alguien de rango superior, otorgándole favor indebido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119210, 'spa', 'Tomar, recibir', 'Tomar o recibir (27 veces): ''tomar esposa'' (Gn 27:3), ''levantar un censo'' (Éx 30:12, lit. ''alzar la cabeza''), ''recibir favor''. El modismo נָשָׂא רֹאשׁ = hacer censo recorre Números. Se solapa con adquisición y aceptación, no con movimiento físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119216, 'spa', 'Ser elevado (Nifal)', 'Formas pasivas del Nifal (19 veces) indican ser alzado o exaltado. ''David comprendió que el SEÑOR lo había exaltado'' (1 Cr 14:2). El sentido pasivo enfoca el estado de elevación resultante, no el acto de elevar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119222, 'spa', 'Portadores de tributo', 'Dos apariciones ambiguas (2 S 8:2, 8:6) glosadas como ''portadores de'' en múltiples lenguas sugieren portadores de tributo u ofrenda. Puede solaparse con el sentido 2 (cargar), pero aplicado a naciones sometidas en vez de sirvientes del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119267, 'spa', 'Levantar falso rumor', '''No levantarás falso testimonio'' (Éx 23:1, 1 vez). La única aparición sugiere ''levantar/propagar'' un rumor falso, aunque algunos traducen ''unirse a'' un informe falso. El contexto involucra testimonio legal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119283, 'spa', 'Enaltecerse (Hitpael)', 'Hitpael reflexivo (3 veces) expresa autoexaltación. ''¿Os enaltecéis sobre la congregación?'' (Nm 16:3). ''Su reino será ensalzado'' (Nm 24:7). La forma reflexiva subraya que el agente actúa sobre sí mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119297, 'spa', 'Alzado, honrado (pasivo)', 'Participio pasivo del Qal (2 veces) describe un estado honorable. ''Traed ofrenda'' (Sal 96:8, lit. ''traed lo alzado/honrado''). ''Vosotros, los llevados por mí desde el nacimiento'' (Is 46:3). El participio pasivo marca el estado resultante de haber sido alzado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119308, 'spa', 'Arrastrar, arrebatar', 'Llevarse por la fuerza (3 veces), por viento o torrente. ''Nuestras iniquidades, como el viento, nos arrastran'' (Is 64:6). ''Los guardias quitaron mi velo'' (Cnt 5:7). El sentido implica remoción por fuerza externa violenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119321, 'spa', 'Vestir, portar sobre sí', 'Llevar puesto sobre la persona (3 veces), referido a vestiduras o equipamiento. ''Ahimelec portando un efod'' (1 S 14:3, lit. ''llevando un efod''). El participio indica el estado continuo de vestir o portar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119324, 'spa', 'Tomar ofrenda pagana', '''No tomaré sus ofrendas de sangre'' (Sal 16:4, 1 vez). David rehúsa participar en libaciones paganas. El sentido se solapa con ''tomar, recibir'' (sentido 3), pero en contexto de rechazo cultual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119330, 'spa', 'Exaltar, sostener (Piel)', 'Piel intensivo (5 veces) indica exaltación activa o sustento. ''El SEÑOR exaltó a David'' (2 S 5:12). Los oficiales de Salomón ''proveyeron'' víveres (1 R 9:11). El Piel añade intensidad o causación al concepto básico de alzar/llevar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119372, 'spa', 'Hacer llevar (Hifil)', 'Hifil causativo (2 veces): hacer que otros carguen. ''Les harán llevar el castigo'' (Lv 22:16). ''Traeremos cuerdas a aquella ciudad'' (2 S 17:13, lit. ''hacer que sea llevada''). El Hifil añade causación: hacer que otro alce o cargue.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119393, 'spa', 'Alzar mano en juramento', '''He alzado mi mano al SEÑOR'' (Gn 14:22, 1 vez, Abraham). El gesto de levantar la mano señala un juramento o promesa solemne ante Dios. Aparición única de esta fórmula juramental específica con נָשָׂא.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119401, 'spa', 'Alzar estandarte', '''Cuando se alza una señal'' (Is 18:3, 1 vez). Se refiere a izar un estandarte o bandera militar de señalización. La construcción temporal ''cuando alzar'' aparece solo aquí con este objeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119417, 'spa', 'Alzar manos en oración', '''Cuando alzo mis manos hacia tu santo santuario'' (Sal 28:2, 1 vez). Gesto de oración con manos alzadas. Similar al sentido 1 (alzar manos) pero en construcción única de súplica ''hacia tu santuario''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119437, 'spa', 'Llevar el arca', '''Tú llevaste el arca de tu rey'' (1 R 2:26, 1 vez, Abiatar). Aparición única referida al papel de Abiatar cargando el arca durante la huida de David. Se solapa con el sentido 2 (cargar) pero en referencia histórica singular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119451, 'spa', 'Levantar y transportar', 'En Daniel 2:35 el viento que «se llevó» los fragmentos de la estatua ilustra el juicio divino dispersando los reinos terrenales sin dejar rastro. Esdras 5:15 usa el imperativo «¡toma!» para transportar vasos sagrados, mientras que Esdras 4:19 emplea el tronco reflexivo para la sublevación sediciosa contra la autoridad. Las traducciones diferencian entre el porte literal y el alzamiento metafórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119452, 'spa', 'Engañar, seducir (Hifil activo) — El sentido principal', 'Engañar, seducir (Hifil activo) — El sentido principal: engañar o desviar activamente a alguien, usado en todas las conjugaciones Hifil. Los enemigos de Ezequías advierten a Judá ''no os engañe'' (2 Re 18:29; Is 36:14), y Jeremías advierte ''no os engañéis a vosotros mismos'' (Jer 37:9). El español ''engañar'', el francés ''tromper'' y el alemán ''betrügen'' convergen en un extravío deliberado, confirmando este como el centro semántico de la raíz en sus 13 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119454, 'spa', 'Ser engañado (Nifal pasivo) — El pasivo Nifal', 'Ser engañado (Nifal pasivo) — El pasivo Nifal: ser engañado o seducido. Aparece una vez en Isaías 19:13, donde los príncipes de Egipto ''han sido engañados'' (en paralelo con ''se han vuelto necios''). El español ''fueron engañados'' preserva claramente la voz pasiva, mostrando que estos líderes son víctimas de su propio falso consejo y no agentes de engaño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119460, 'spa', 'Sobrevenir, sorprender — Un sentido extendido de aparición súbita o acometida, p', 'Sobrevenir, sorprender — Un sentido extendido de aparición súbita o acometida, presente en el Salmo 55:15 donde el salmista pide que la muerte ''acometa'' a los malvados. El español ''acometa'' refleja este desplazamiento del engaño cognitivo a la emboscada física; ambos comparten el hilo semántico de ser tomado desprevenido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119465, 'spa', 'Totalmente, completamente (Qal intensificador) — Un uso adverbial poco frecuente', 'Totalmente, completamente (Qal intensificador) — Un uso adverbial poco frecuente como infinitivo absoluto Qal que intensifica un verbo cercano, presente en Jeremías 23:39. Las traducciones multilingües divergen notablemente — el inglés ''lifting'', el español ''olvidando'', el francés ''tromper'' — reflejando la incertidumbre sobre si deriva de la misma raíz o de una homónima que significa ''levantar'' u ''olvidar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119466, 'spa', 'Acreedor y prestamista', 'Designa el papel o la acción del acreedor, aquel que presta con interés o tiene un derecho financiero sobre otro. El participio qal (נֹשֶׁא) funciona como sustantivo con el sentido de «acreedor», mientras que el hifil (יַשִּׁיא) significa «exigir» o «actuar como acreedor». Las traducciones multilingües lo vierten de forma consistente como «acreedor» o «exigir/cobrar pago» (deudor, créditeur, Gläubiger).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119468, 'spa', 'Soplar y dispersar', 'El uso teológico de Isaías contrasta la fragilidad humana con la palabra eterna de Dios: el aliento divino marchita toda carne como hierba abrasada por el viento. El Salmo celebra el dominio soberano de Dios sobre el clima, cuyo viento derrite el hielo invernal. Génesis preserva el sentido de ahuyentar soplando, donde Abraham espanta las aves de rapiña del sacrificio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119469, 'spa', 'Poder costear, tener medios suficientes — 10 ocurrencias concentradas en Levític', 'Poder costear, tener medios suficientes — 10 ocurrencias concentradas en Levítico 14 y 25, todas en la expresión idiomática ''si su mano alcanza / no alcanza''. Esta metáfora económica — la mano que se extiende hacia el precio requerido pero quizás no llega — genera el sistema levítico de ofrendas proporcionales (Lv 14:21-32) y las disposiciones de rescate de tierras (Lv 25:26-28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119471, 'spa', 'Dar alcance en la persecución — el sentido dominante con 28 ocurrencias, present', 'Dar alcance en la persecución — el sentido dominante con 28 ocurrencias, presente en textos narrativos y legales. Labán alcanza a Jacob (Gn 31:25), el mayordomo de José alcanza a los hermanos (Gn 44:4-6), los carros del faraón alcanzan a Israel junto al Mar Rojo (Éx 14:9) y el vengador de sangre puede dar alcance al homicida (Dt 19:6). El verbo se asocia frecuentemente con רָדַף (''perseguir''), creando una secuencia dramática de caza y captura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119478, 'spa', 'Alcanzar o llegar a un punto, límite o momento — 9 ocurrencias donde el énfasis ', 'Alcanzar o llegar a un punto, límite o momento — 9 ocurrencias donde el énfasis recae en lograr una meta más que en perseguir a una persona. Los años de Jacob ''no alcanzaron'' los años de sus padres (Gn 47:9); la trilla ''alcanzará'' la vendimia (Lv 26:5); la mano ''no alcanza'' ni siquiera la décima parte de un efa (Lv 5:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119481, 'spa', 'Mover o desplazar linderos — una sola ocurrencia en Job 24', 'Mover o desplazar linderos — una sola ocurrencia en Job 24:2 que describe a los impíos que ''mueven los mojones''. El sentido es debatido: algunos lo interpretan como ''quitan los linderos'', otros como ''invaden'' la tierra del prójimo. El versículo se sitúa en la frontera entre este verbo y otros campos semánticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119495, 'spa', 'Obtener gozo o bendición, especialmente en promesas escatológicas — 2 ocurrencia', 'Obtener gozo o bendición, especialmente en promesas escatológicas — 2 ocurrencias en versículos proféticos casi idénticos. En Is 35:10 y 51:11 los redimidos ''obtendrán gozo y alegría'', donde el verbo transforma la metáfora de persecución en una visión de bendiciones que alcanzan activamente al pueblo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119509, 'spa', 'Olvidar (Qal/Nifal)', 'Formas intransitivas Qal y Nifal que significan olvidar o ser olvidado. En Lam 3:17 el hablante ha olvidado la prosperidad, expresando duelo personal. En Jer 23:39 Dios declara que olvidara a su pueblo en juicio, mientras que Isa 44:21 asegura que no sera olvidado por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119510, 'spa', 'Hacer olvidar (Piel/Hifil)', 'Formas causativas Piel e Hifil que significan hacer que alguien olvide. En Gen 41:51 Jose nombra a Manases porque Dios le hizo olvidar su afliccion, donde el olvido es don de gracia. Job 11:6 sugiere que Dios hace olvidar parte de la iniquidad, y Job 39:17 lo aplica al avestruz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119515, 'spa', 'prestar (Qal)', 'El sentido verbal básico en Qal de prestar dinero o bienes a otra persona, normalmente construido con la preposición bêt para el receptor del préstamo. Jeremías 15:10 empareja activo y pasivo (''no presté, ni me prestaron'') para expresar total inocencia social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119517, 'spa', 'exigir, cobrar deuda', 'Una única aparición en Nehemías 5:7 donde el sentido se inclina hacia exigir o presionar por el cobro de una deuda: Nehemías reprende a los nobles por exigir opresivamente el pago a sus hermanos judíos. El español ''cargáis'' capta la cualidad coercitiva y extractiva que lo distingue del préstamo neutro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119518, 'spa', 'acreedor, tenedor de deuda', 'El participio Qal empleado como sustantivo: el acreedor, quien posee la deuda. Esta figura aparece investida de poder legal y a veces amenazante — el acreedor que viene a tomar a los hijos de la viuda como esclavos (2 R 4:1), o como categoría social en Isaías 24:2 donde acreedor y deudor enfrentan el juicio por igual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119520, 'spa', 'prestar (Hifil causativo)', 'La forma causativa Hifil, que significa hacer que se preste o conceder un préstamo, presente en las regulaciones de Deuteronomio. En Dt 15:2 todo acreedor ''remitirá'' lo que haya prestado, y en 24:10 se dan instrucciones sobre cómo actuar ''cuando prestes'' al prójimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119530, 'spa', 'líder, jefe tribal', 'Cabeza designada de un grupo tribal, clánico o comunitario, en particular los jefes de las doce tribus de Israel nombrados para el censo y la organización del campamento (Nm 2:3-29). El término aparece en listas formularias (Nm 1:5-16; 7:10-83) donde cada líder representa la casa paterna de su tribu ante la congregación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119533, 'spa', 'príncipe, gobernante soberano', 'Príncipe soberano o gobernante exaltado que ejerce autoridad regia, especialmente el príncipe escatológico de Ezequiel (Ez 34:24; 44:3; 45:7-8). En Éxodo 22:28 el término aparece en paralelo con אֱלֹהִים, señalando a un gobernante al que no se debe maldecir, lo cual indica un estatus casi monárquico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119556, 'spa', 'Nubes y vapores', 'Designa nubes o vapores ascendentes, particularmente los asociados con la lluvia. El término aparece en contextos poéticos y proféticos que describen el dominio soberano de Dios sobre el clima (Jeremías 10:13; 51:16; Salmo 135:7) y en el símil de Proverbios 25:14 sobre nubes sin lluvia. La mayoría de las traducciones lo vierten como «nubes» (nuages, Wolken, clouds).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119560, 'spa', 'Morder (Qal literal)', 'La mordedura literal de una criatura, especialmente una serpiente, en la conjugación Qal. Génesis 49:17 presenta a Dan como una serpiente que muerde los talones del caballo; Números 21:8-9 emplea tanto el participio activo (''el que muerde'') como el pasivo (''el mordido''). Proverbios 23:32 y Eclesiastés 10:8, 11 extienden la imagen al vino que ''muerde como serpiente''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119563, 'spa', 'Cobrar interés usurario', 'Extensión metafórica a la depredación financiera: cobrar intereses usurarios o ''morder'' al deudor mediante préstamos opresivos. Habacuc 2:7 pregunta al tirano: ''¿No se levantarán de repente tus acreedores (literalmente, los que te muerden)?'' El camino semántico de los colmillos de la serpiente a la garra del acreedor refleja una intuición antigua sobre la naturaleza depredadora de la explotación financiera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119568, 'spa', 'Morder gravemente (Piel)', 'Mordedura grave o repetida en la conjugación Piel intensiva, que enfatiza la letalidad del ataque. Números 21:6 relata las serpientes ardientes que ''mordieron'' al pueblo con resultados fatales; Jeremías 8:17 amenaza con serpientes que ''os morderán'' sin que encantador alguno pueda impedirlo. No se trata de un mordisco aislado, sino de un asalto sostenido y letal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119572, 'spa', 'Prestar con usura', 'Describe el acto de prestar dinero a interés o cobrar usura. Deuteronomio 23:19-20 emplea tanto las formas Qal como Hifil para regular los préstamos con interés: los israelitas podían cobrar intereses a los extranjeros, pero no a sus compatriotas. Las cuatro apariciones reflejan la formulación legal detallada, y las glosas multilingües coinciden en términos de interés y usura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119573, 'spa', 'Interés, usura', 'Interés o usura cobrada sobre préstamos, condenada en la ley israelita. Prohibida entre israelitas (Ex 22:25; Lv 25:36-37; Dt 23:19-20), aunque permitida hacia extranjeros. Ezequiel la cuenta entre pecados capitales (Ez 18:8, 13, 17; 22:12), y el Salmo 15:5 señala abstenerse de ella como marca del justo. La etimología desde nashakh (''morder'') capta la naturaleza depredadora del préstamo explotador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119579, 'spa', 'Cámara o almacén', 'Las tres apariciones se encuentran en los relatos de reconstrucción y reforma de Nehemías. La cámara personal (3:30) muestra aposentos asignados a individuos junto al muro. El incidente de Tobías (13:7) ilustra cómo las cámaras podían ser reasignadas indebidamente para alojar a un extranjero en el recinto del templo. Las cámaras del tesoro (12:44) resguardaban las contribuciones sagradas de la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119580, 'spa', 'Expulsar, desposeer (naciones)', 'Expulsar o desposeer naciones de su tierra — el sentido transitivo Qal/Piel de remoción forzosa. Dt 7:1 y 7:22 describen a YHWH «expulsando» (וְנָשַׁל) a las naciones cananeas, y 2 R 16:6 lo emplea para la expulsión de Judá por parte de Edom. Es la extensión más fuerte de la raíz, que pasa del desprendimiento físico al desplazamiento territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119581, 'spa', 'Quitar (sandalias)', 'Sacarse o quitarse las sandalias — el sentido Qal imperativo de remoción deliberada del calzado en tierra santa. Éx 3:5 junto a la zarza ardiente y Jos 5:15 ante Jericó emplean שַׁל como mandato divino. Se trata de un acto voluntario de reverencia, distinto del deslizamiento involuntario del sentido 3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119582, 'spa', 'Deslizarse, desprenderse, caer', 'Soltarse, desprenderse o caer involuntariamente — el sentido Qal intransitivo. En Dt 19:5 el hierro del hacha «se suelta» (וְנָשַׁל) del mango de madera, y Dt 28:40 advierte que las aceitunas «se caerán» como maldición del pacto. Transmite un desprendimiento accidental, impulsado por la gravedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119588, 'spa', 'Aliento físico — el aire inhalado y exhalado por los seres vivos, y de manera su', 'Aliento físico — el aire inhalado y exhalado por los seres vivos, y de manera suprema el aliento de vida insuflado por Dios en la humanidad. La נִשְׁמַת חַיִּים de Génesis 2:7 es el don animador; Génesis 7:22 añade רוּחַ para intensificar la expresión. Job 27:3 y 33:4 afirman que mientras el aliento de Dios permanezca en la persona, esta vive.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119592, 'spa', 'La ráfaga poderosa de las narices de Dios — imagen teofánica de la ira divina', 'La ráfaga poderosa de las narices de Dios — imagen teofánica de la ira divina. En 2 Samuel 22:16 y Salmo 18:15 la נְשָׁמָה del enojo de Dios descubre el lecho del mar; en Job 4:9 los impíos perecen por ella; en Job 37:10 congela el agua en hielo. Se trata de una fuerza violenta y ventosa, distinta del aliento suave.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119596, 'spa', 'Por metonimia, un alma viviente o criatura que respira — todo aquello que tiene ', 'Por metonimia, un alma viviente o criatura que respira — todo aquello que tiene aliento. Josué 10:40 informa de la destrucción de ''toda נְשָׁמָה'', es decir, todo ser viviente. Isaías 57:16 lo extiende a las ''almas'' colectivas que Dios ha creado. El paso de aliento a ser que respira es natural en las lenguas semíticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119604, 'spa', 'Crepúsculo vespertino, ocaso', 'Crepúsculo vespertino u ocaso: la luz que se desvanece tras la puesta del sol. Sentido dominante, presente en diez de doce apariciones. Conlleva connotaciones de ocultamiento y ambigüedad moral: el adúltero «acecha el crepúsculo» (Job 24:15) y la seductora merodea «al anochecer» (Pr 7:9). Isaías 5:11 advierte a quienes se demoran hasta la tarde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119611, 'spa', 'Crepúsculo matutino, alba', 'Crepúsculo matutino o alba: la luz emergente antes del amanecer. Solo dos apariciones portan este sentido. Job 7:4 describe al insomne dando vueltas hasta el alba (נֶשֶׁף), anhelando que termine la noche. El Salmo 119:147 declara «me adelanté al alba y clamé». El cambio de tarde a mañana lo determina el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119615, 'spa', 'Encender y quemar', 'El Salmo emplea el Nifal pasivo para la ira divina que se enciende espontáneamente contra el pecado: el fuego como metáfora de la indignación feroz de Dios. Isaías en Hifil activo describe el acto cotidiano de prender fuego para calentarse, contrastando el uso práctico con la insensatez idolátrica. La profecía de Ezequiel transforma espadas en leña, la inversión suprema donde instrumentos de muerte se convierten en combustible para la supervivencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119616, 'spa', 'El sentido básico del Qal cubre el acto cotidiano de besar como saludo, despedid', 'El sentido básico del Qal cubre el acto cotidiano de besar como saludo, despedida o afecto entre personas. Jacob besa a su padre Isaac (Gn 27:26-27), Raquel recibe un beso de Jacob junto al pozo (Gn 29:11), y Esaú abraza a su hermano distanciado (Gn 33:4). Las glosas multilingües lo traducen consistentemente como ''besó/baiser/küsste,'' confirmando un núcleo intercultural estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119619, 'spa', 'La forma intensiva del Piel denota besar con fervor o repetidamente, deslizándos', 'La forma intensiva del Piel denota besar con fervor o repetidamente, deslizándose hacia el homenaje cultual. El Salmo 2:12 ordena ''honrad al Hijo'' como acto de sumisión, mientras Génesis 45:15 describe a José besando a todos sus hermanos en una escena de reunión emotiva. Los traductores leen homenaje más que mero afecto en la conjugación intensiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119637, 'spa', 'Una única ocurrencia del Hifil en Ezequiel 3', 'Una única ocurrencia del Hifil en Ezequiel 3:13 describe las alas de los seres vivientes ''tocándose'' entre sí, una extensión causativa de los labios a las superficies. La partida del lenguaje de ''besar'' en las traducciones confirma esto como un sentido distinto de contacto físico, ya no afecto interpersonal sino adyacencia de objeto a objeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119638, 'spa', 'Armado con arco', 'Las tres apariciones se dan en contextos militares que describen unidades de arqueros dentro de las fuerzas de Israel. Los arqueros benjaminitas (1 Crónicas 12:2) son guerreros de élite que se unen al ejército de David. Los arqueros armados de Efraín (Salmo 78:9) ejemplifican la infidelidad al pacto: el equipamiento sin lealtad es inútil. El censo de Crónicas (17:17) documenta la fuerza militar de Josafat, incluyendo tropas con arco y escudo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119639, 'spa', 'Armas, armamento', 'Armas o equipo militar como término colectivo. Abarca toda la gama de pertrechos sin especificar tipo, a menudo seguido de nombres concretos (como en Ez 39:9, donde נֶשֶׁק es la categoría general y luego se enumeran arcos, flechas, mazas y lanzas). Se aplica a armas como tributo (1 R 10:25), en ciudades fortificadas (Is 22:8) y metafóricamente para la batalla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119643, 'spa', 'Armería, arsenal', 'Armería o arsenal: lugar donde se guardan las armas. En Nehemías 3:19, el término con artículo (הַנֶּשֶׁק) identifica un lugar específico a lo largo de los muros de Jerusalén: «frente a la subida de la armería, en el ángulo». Esta extensión metonímica del contenido (armas) al contenedor (depósito) es un desarrollo semántico natural, comparable al español «armas» > «armería».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119647, 'spa', 'Ave rapaz de gran tamaño — ya sea el águila real o el buitre leonado — usada lit', 'Ave rapaz de gran tamaño — ya sea el águila real o el buitre leonado — usada literal y metafóricamente. Como criatura literal, se remonta a grandes alturas (Job 39:27), anida en peñascos (Job 39:28) y es ritualmente impura (Lv 11:13; Dt 14:12). Metafóricamente representa el poder protector de Dios (Éx 19:4; Dt 32:11), la rapidez militar (Dt 28:49; Hab 1:8; 2 S 1:23) y la transitoriedad de la riqueza (Pr 23:5). Isaías 40:31 promete que quienes esperan en el SEÑOR remontarán alas como águilas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119658, 'spa', 'Secarse o agotarse', 'Los dos pasajes de Isaías emplean el secarse literal: lenguas resecas por la sed (41:17) y las aguas del Nilo que se agotan (19:5), ambos representando una escasez devastadora. El uso de Jeremías transforma lo físico en metafórico: la fuerza guerrera «se seca» como las fuentes de agua que fallan, el coraje que se evapora en la crisis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119660, 'spa', 'Carta oficial', 'Las tres apariciones funcionan dentro de la burocracia persa que gobernaba la restauración de Judá. Las cartas median el poder real: acusaciones contra los judíos (4:18), decretos reales que detienen la obra (4:23) y peticiones de búsqueda en los archivos (5:5). La forma enfática sugiere documentación formal y oficial, no correspondencia personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119661, 'spa', 'Cortar en pedazos', 'Cortar un cuerpo en piezas por sus articulaciones, en la forma Piel, tanto para el despiece ritual como para el descuartizamiento simbólico. En el contexto sacrificial (Lv 1:6, 12; 8:20; Éx 29:17; 1 R 18:23, 33), el verbo describe el método prescrito para preparar un holocausto. En el contexto narrativo (Jue 19:29; 20:6; 1 S 11:7), describe el envío de partes del cuerpo como convocatoria urgente a la acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119668, 'spa', 'trozo de res descuartizada', 'Una porción o pieza resultante del corte ritual o deliberado de la res de un animal. Se usa predominantemente en contextos sacrificiales donde el sacerdote levítico descuartiza el holocausto y dispone sus trozos sobre el fuego del altar (Éx 29:17; Lv 1:6, 8, 12; 8:20; 9:13). Ezequiel emplea el término simbólicamente para los habitantes de Jerusalén como ''pedazos de carne'' en una olla hirviente bajo el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119676, 'spa', 'Senda, camino, sendero', 'Senda, vereda o curso de viaje, usado en contextos figurados y sapienciales para la direccion moral de la vida. En Job describe senderos ocultos (28:7) y caminos donde se tienden trampas (18:10); en los Salmos se convierte en la senda de los mandamientos de Dios (119:35). Sugiere un camino estrecho e intimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119682, 'spa', 'Senda, vereda, camino secundario — Un camino físico, vereda o sendero, una ruta ', 'Senda, vereda, camino secundario — Un camino físico, vereda o sendero, una ruta por la que se transita, típicamente más pequeña o menos establecida que el camino principal (דֶּרֶךְ). En Jueces 5:6, el paralelismo con אֳרָחוֹת (caminos) subraya que las נְתִיבוֹת son rutas secundarias a las que recurren los viajeros en tiempos peligrosos. Job 38:20 usa el término para las ''sendas'' hacia las moradas de la luz y las tinieblas — caminos cósmicos con un carácter casi geográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119685, 'spa', 'Camino de vida o conducta — Una senda figurada que denota un curso de vida, cond', 'Camino de vida o conducta — Una senda figurada que denota un curso de vida, conducta o dirección moral. Job 19:8 lamenta que Dios ha ''tapiado mi camino'' (נְתִיבֹתַי), y Lamentaciones 3:9 hace eco con ''ha torcido mis sendas''. El Salmo 119:105 — ''lumbrera a mi camino'' — se ha convertido en uno de los versículos más amados de la Escritura, y el hebreo usa específicamente נְתִיבָה en lugar de דֶּרֶךְ, sugiriendo un caminar íntimo y personal con Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119700, 'spa', 'Netineos, sirvientes del templo — Una clase dedicada de sirvientes hereditarios ', 'Netineos, sirvientes del templo — Una clase dedicada de sirvientes hereditarios del templo cuyo título, derivado del pasivo de natan (''dar''), los señala como personas formalmente ''entregadas'' al servicio sagrado. Asistían a los levitas en las tareas humildes del santuario y son cuidadosamente enumerados entre los que retornaron del exilio (Esd 2:43-58; Neh 7:46-60), distinguidos de sacerdotes, levitas y porteros. Residían en el Ofel, cerca del templo (Neh 3:26; 11:21), y la tradición atribuye su designación a David (Esd 8:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119705, 'spa', 'Ser derramado (líquido) — El sentido primario Qal y Nifal', 'Ser derramado (líquido) — El sentido primario Qal y Nifal: ser derramado como un líquido. Casi siempre figurado, describiendo la ira divina derramada sobre personas o lugares (Jer 42:18; 44:6; 2 Cr 12:7; 34:25), o gemidos que brotan como agua (Job 3:24). La lluvia que deja de ''derramarse'' en Éxodo 9:33 es una de las pocas instancias literales. El español ''derramar'' y el francés ''verser'' apuntan consistentemente al vertido de líquidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119711, 'spa', 'Ser fundido o refinado — El sentido Nifal y Hofal de ser fundido o refinado, esp', 'Ser fundido o refinado — El sentido Nifal y Hofal de ser fundido o refinado, específicamente de metales en un horno. Ezequiel 22:21-22 y 24:11 emplean esta imagen de Israel reunido en Jerusalén como metales en un crisol para un juicio purificador. El español ''fundir'' y el cambio del vocabulario de ''derramar'' al de ''fundir'' marcan esto como un dominio semántico distinto: procesamiento metalúrgico en lugar de vertido de líquidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119715, 'spa', 'Derramar (causativo) — El sentido causativo Hifil aplicado al vertido', 'Derramar (causativo) — El sentido causativo Hifil aplicado al vertido: derramar activamente, a diferencia del sentido de fundición. Job 10:10 usa la imagen impactante ''¿No me derramaste como leche?'' — Dios como artesano vertiendo la vida humana. En 2 Crónicas 34:17 el dinero del templo es ''derramado'' (distribuido). El español ''derramar'' reaparece aquí en lugar de ''fundir'', confirmando que se trata del vertido de líquidos y no de procesamiento metalúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119719, 'spa', 'Hacer fundir o refinar — El sentido causativo Hifil aplicado a la fundición', 'Hacer fundir o refinar — El sentido causativo Hifil aplicado a la fundición: fundir o refinar metales activamente. En Ezequiel 22:20, Dios declara ''os reuniré y os fundiré'', y en 2 Reyes 22:9 se informa que la plata del templo fue ''vertida'' (es decir, fundida y distribuida). El agente Hifil inicia deliberadamente la transformación metalúrgica como acto de juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119724, 'spa', 'Dar, otorgar', 'El sentido predeterminado y abrumadoramente dominante: dar, otorgar o transferir posesión. Abarca regalos (Gn 24:53), pagos (Gn 23:13), concesiones divinas (Gn 12:7) y ofrendas (Gn 14:20). Con 1.855 de unas 2.015 apariciones, constituye el significado no marcado de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119756, 'spa', 'Hacer, constituir', 'Sentido transformativo-causativo: hacer, convertir o constituir a alguien en un nuevo estado o función. José es constituido gobernador de Egipto (Gn 41:43), Dios promete hacer de Abraham una gran nación, y el orgullo de Israel se vuelve como hierro (Lv 26:19). El árabe جَعَلَ (''hacer/convertir'') confirma la distinción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119778, 'spa', 'Poner, colocar', 'Extensión espacial-locativa: poner, colocar o situar algo en una posición. Incluye poner el arco iris como señal (Gn 9:13), colocar un anillo en la mano (Gn 41:42) y el modismo ''poner el rostro hacia'' indicando atención dirigida. Las glosas multilingües distinguen claramente este sentido del de dar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119802, 'spa', 'Ser dado, ser entregado (Nifal)', 'Nifal pasivo y participio pasivo del Qal: ser dado, entregado o repartido por un agente no especificado. Aparece en contextos legales como ''herida por herida será dada'' (Lv 24:20) y en la distribución de herencia tribal (Nm 26:54).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119868, 'spa', 'Permitir, dejar', 'Sentido permisivo: permitir, dejar o consentir que alguien actúe. Dios no dejó que Labán dañara a Jacob (Gn 31:7), Israel no permitió a los danitas bajar (Jue 1:34), y el suegro de Sansón le impidió entrar (Jue 15:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119873, 'spa', 'Entregar, rendir', 'Sentido militar-judicial: entregar, rendir o poner en poder de otro. Dios entrega a los enemigos en manos de Israel (Dt 7:24), Sijón es entregado (Dt 2:30) y las naciones son dadas a la matanza (Is 34:2). El español entregar y el árabe سَلَّمَ distinguen claramente este sentido del dar neutro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119967, 'spa', 'Dar (variante residual)', 'Aparición residual en 2 Cr 24:9, donde el verbo aparece en el contexto de una proclamación de colecta sobre el tributo de Moisés. Las glosas multilingües apuntan al sentido ordinario de ''dar''; probablemente una variante formal que el algoritmo de agrupamiento aisló.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119987, 'spa', 'Dar, otorgar', 'Dar, otorgar o conceder, abarcando actos humanos de entrega y la concesión divina de autoridad. En Dn 4:17,25,32 expresa la prerrogativa soberana de Dios de «dar» el dominio terrenal a quien elija — afirmación teológica clave en los relatos cortesanos arameos. Dn 2:16 lo usa cuando Daniel pide tiempo al rey, y Esd 4:13 se refiere al pago de tributos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119992, 'spa', 'El nombre propio Natán (''él dio''), portado de manera más prominente por el profe', 'El nombre propio Natán (''él dio''), portado de manera más prominente por el profeta que entregó el oráculo del pacto davídico (2 Sam 7), pronunció juicio tras el asunto de Betsabé (2 Sam 12:1-15) y aseguró la coronación de Salomón (1 Re 1). También identifica a un hijo de David (2 Sam 5:14), al padre de un guerrero (2 Sam 23:36) y a figuras postexílicas (Esd 8:16; 10:39). Las 42 ocurrencias abarcan a varios individuos, pero el profeta domina el registro bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (119996, 'spa', 'Natanael (nombre propio)', 'Un nombre propio teofórico que significa ''Dios ha dado'', portado por varias figuras bíblicas. El más destacado es el líder de Isacar durante el período del desierto, que aparece en el censo, la disposición del campamento y la dedicación del tabernáculo (Nm 1:8; 2:5; 7:18, 23; 10:15). Otros portadores incluyen al cuarto hijo de Isaí (1 Cr 2:14), músicos y escribas levíticos (1 Cr 15:24; 24:6) y un portero (1 Cr 26:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120000, 'spa', 'Netanías, Netanyahu (nombre propio) — El nombre propio Netanías/Netanyahu (netan', 'Netanías, Netanyahu (nombre propio) — El nombre propio Netanías/Netanyahu (netan-yahu, ''Yahvé ha dado''), referido a múltiples individuos: el más notable es el padre de Ismael, quien asesinó al gobernador Gedalías (2 Re 25:23, 25; Jer 40:8-41:18); también el padre de Jehudí (Jer 36:14), un maestro levita (2 Cr 17:8) y un cantor del templo (1 Cr 25:2, 12). La forma larga Netanyahu y la más corta Netanías representan el mismo nombre con variantes ortográficas que alternan libremente en el texto hebreo.');